        status: "active",
        position: "Developer",
        department_id: null,
        role_id: null,
        organization_id: organization.id,
        user_id: member.id,
      } satisfies IHrmTrackerEmployee.ICreate,
    },
  );
  // 4. Retrieve role change history (will be empty since no roles were assigned)
