    memberConnection,
    {
      body: {
        page: 1,
        limit: 10,
        search: RandomGenerator.name(3),
        status: "active",
      } satisfies IHrmTrackerProject.IRequest,
    },
  );
  typia.assert(createProject);
  if (createProject.data.length === 0) {
