import { ArrayUtil } from "@nestia/e2e";
import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/sdk";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";

import { MyGlobal } from "../MyGlobal";
import { MemberPayload } from "../decorators/payload/MemberPayload";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

export async function patchHrmTrackerMemberTimesheetsMetrics(props: {
  member: MemberPayload;
  body: IHrmTrackerTimesheet.IRequest;
}): Promise<IPageIHrmTrackerTimesheet.ISummary> {
  const page = props.body.page ?? 1;
  const limit = props.body.limit ?? 20;
  const skip = (page - 1) * limit;
  // Authorization: Check permissions
  const hasViewAll =
    await MyGlobal.prisma.hrm_tracker_role_permissions.findFirst({
      where: {
        role: {
          employees: {
            some: {
              id: props.member.id,
              deleted_at: null,
            },
          },
        },
        permission: {
          permission: "time:view_all",
        },
      },
    });
  const hasProjectAccess = !hasViewAll
    ? await MyGlobal.prisma.hrm_tracker_project_members.findFirst({
        where: {
          hrm_tracker_employee_id: props.member.id,
          deleted_at: null,
        },
        select: { project: { select: { id: true } } },
      })
    : null;
  // Build where clause for timesheets
  const where: Prisma.hrm_tracker_timesheetsWhereInput = {
    deleted_at: null,
    status: props.body.status,
    week_start_date: props.body.week_start_date
      ? {
          gte: new Date(props.body.week_start_date + "T00:00:00.000Z"),
        }
      : undefined,
    week_end_date: props.body.week_end_date
      ? {
          lte: new Date(props.body.week_end_date + "T23:59:59.999Z"),
        }
      : undefined,
  };
  if (!hasViewAll && !hasProjectAccess) {
    // Self-view only - filter by employee relation
    const employee = await MyGlobal.prisma.hrm_tracker_employees.findFirst({
      where: {
        id: props.member.id,
        deleted_at: null,
      },
      select: { id: true },
    });
    if (!employee) {
      return {
        pagination: {
          current: page,
          limit: limit,
          records: 0,
          pages: 0,
        },
        data: [],
      };
    }
    where.employee = {
      id: employee.id,
    };
  } else if (!hasViewAll && hasProjectAccess) {
    // Project-based access - get employees in the same project
    const projectEmployeeIds =
      await MyGlobal.prisma.hrm_tracker_project_members.findMany({
        where: {
          project: {
            id: hasProjectAccess.project.id,
          },
          deleted_at: null,
        },
        select: { hrm_tracker_employee_id: true },
      });
    if (projectEmployeeIds.length === 0) {
      return {
        pagination: {
          current: page,
          limit: limit,
          records: 0,
          pages: 0,
        },
        data: [],
      };
    }
    where.hrm_tracker_employee_id = {
      in: projectEmployeeIds.map((pe) => pe.hrm_tracker_employee_id),
    };
  }
  // Fetch timesheets
  const timesheets = await MyGlobal.prisma.hrm_tracker_timesheets.findMany({
    where: where,
    skip: skip,
    take: limit,
    orderBy: props.body.search
      ? ({
          week_start_date: "desc",
        } satisfies Prisma.hrm_tracker_timesheetsOrderByWithRelationInput)
      : { week_start_date: "desc" },
  });
  const total = await MyGlobal.prisma.hrm_tracker_timesheets.count({
    where: where,
  });
  // Transform to summary format with proper date handling
  const data: IHrmTrackerTimesheet.ISummary[] = timesheets.map((t) => ({
    id: t.id,
    employee_id: t.hrm_tracker_employee_id,
    organization_id: t.hrm_tracker_organization_id,
    week_start_date: toISOStringSafe(t.week_start_date),
    week_end_date: toISOStringSafe(t.week_end_date),
    status: t.status as "draft" | "submitted" | "approved" | "rejected",
    total_hours: t.total_hours,
    submitted_at: t.submitted_at ? toISOStringSafe(t.submitted_at) : null,
    reviewed_at: t.reviewed_at ? toISOStringSafe(t.reviewed_at) : null,
  }));
  return {
    pagination: {
      current: page,
      limit: limit,
      records: total,
      pages: Math.ceil(total / limit),
    },
    data: data,
  };
}

import { IEntity } from "@ORGANIZATION/PROJECT-api/lib/structures/IEntity";
import { IHrmTrackerEmployee } from "@ORGANIZATION/PROJECT-api/lib/structures/IHrmTrackerEmployee";
import { ArrayUtil } from "@nestia/e2e";
import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/sdk";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";

import { MyGlobal } from "../MyGlobal";
import { MemberPayload } from "../decorators/payload/MemberPayload";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

export async function postHrmTrackerMemberEmployeesEmployeeIdRole(props: {
  member: MemberPayload;
  employeeId: string & tags.Format<"uuid">;
  body: IHrmTrackerEmployee.IAssign;
}): Promise<void> {
  const { member, employeeId, body } = props;
  const now = toISOStringSafe(new Date());
  const employee =
    await MyGlobal.prisma.hrm_tracker_employees.findUniqueOrThrow({
      where: { id: employeeId },
      select: {
        id: true,
        organization_id: true,
        role_id: true,
        user_id: true,
      },
    });
  const organization =
    await MyGlobal.prisma.hrm_tracker_organizations.findUniqueOrThrow({
      where: { id: employee.organization_id },
      select: {
        id: true,
        owner_member_id: true,
      },
    });
  // Find the member's own employee record in the same organization
  const memberEmployee =
    await MyGlobal.prisma.hrm_tracker_employees.findFirstOrThrow({
      where: {
        user_id: member.id,
        organization_id: employee.organization_id,
        deleted_at: null,
      },
      select: { id: true, role_id: true },
    });
  // If member has no role, they can't have permissions
  if (memberEmployee.role_id === null) {
    throw new HttpException("Forbidden", 403);
  }
  // Check if member's role has 'employee:manage' permission by joining through role_permissions
  const rolePermissions =
    await MyGlobal.prisma.hrm_tracker_role_permissions.findMany({
      where: {
        role_id: memberEmployee.role_id,
      },
      select: {
        permission_id: true,
      },
    });
  if (rolePermissions.length === 0) {
    throw new HttpException("Forbidden", 403);
  }
  // Get the actual permission records to check for 'employee:manage'
  const permissions = await MyGlobal.prisma.hrm_tracker_permissions.findMany({
    where: {
      id: { in: rolePermissions.map((rp) => rp.permission_id) },
    },
  });
  // Check if any permission has the 'employee:manage' code
  const hasManagePermission = permissions.some(
    (p) => p.permission === "employee:manage",
  );
  // Only owners or users with employee:manage permission can assign roles
  if (organization.owner_member_id !== member.id && !hasManagePermission) {
    throw new HttpException("Forbidden", 403);
  }
  if (body.role_id !== undefined && body.role_id !== null) {
    // Verify role belongs to the same organization
    const role = await MyGlobal.prisma.hrm_tracker_roles.findUniqueOrThrow({
      where: { id: body.role_id },
      select: {
        id: true,
        hrm_tracker_organization_id: true,
      },
    });
    if (role.hrm_tracker_organization_id !== employee.organization_id) {
      throw new HttpException(
        "Role does not belong to employee's organization",
        400,
      );
    }
    await MyGlobal.prisma.hrm_tracker_employees.update({
      where: { id: employeeId },
      data: {
        role_id: body.role_id,
        updated_at: now,
      },
    });
    await MyGlobal.prisma.hrm_tracker_activity_logs.create({
      data: {
        id: v4() as string & tags.Format<"uuid">,
        hrm_tracker_member_id: member.id,
        target_entity_type: "employee",
        target_entity_id: employeeId,
        action_type: "role_assigned",
        created_at: now,
      },
    });
  } else {
    await MyGlobal.prisma.hrm_tracker_employees.update({
      where: { id: employeeId },
      data: {
        role_id: null,
        updated_at: now,
      },
    });
    await MyGlobal.prisma.hrm_tracker_activity_logs.create({
      data: {
        id: v4() as string & tags.Format<"uuid">,
        hrm_tracker_member_id: member.id,
        target_entity_type: "employee",
        target_entity_id: employeeId,
        action_type: "role_removed",
        created_at: now,
      },
    });
  }
}

import { IEntity } from "@ORGANIZATION/PROJECT-api/lib/structures/IEntity";
