import { HrmTrackerOrganizationAtSummaryTransformer } from "../transformers/HrmTrackerOrganizationAtSummaryTransformer";
import { HrmTrackerProjectTransformer } from "../transformers/HrmTrackerProjectTransformer";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

export async function postHrmTrackerMemberProjectsProjectIdStatusChange(props: {
  member: MemberPayload;
  projectId: string;
}): Promise<IHrmTrackerProject> {
  // Fetch project with organization context for authorization and current status
  const project = await MyGlobal.prisma.hrm_tracker_projects.findUniqueOrThrow({
    where: { id: props.projectId, deleted_at: null },
    select: {
      id: true,
      name: true,
      status: true,
      hrm_tracker_organization_id: true,
      organization: HrmTrackerOrganizationAtSummaryTransformer.select(),
    },
  });
  // Verify actor has project:manage permission via role
  const roleAssignment =
    await MyGlobal.prisma.hrm_tracker_employee_roles.findFirst({
      where: {
        employee: {
          member_id: props.member.id,
          deleted_at: null,
        },
        hrm_tracker_organization_id: project.hrm_tracker_organization_id,
      },
      select: {
        role_id: true,
      },
    });
  if (!roleAssignment) {
    throw new HttpException("Forbidden", 403);
  }
  const role = await MyGlobal.prisma.hrm_tracker_roles.findUniqueOrThrow({
    where: { id: roleAssignment.role_id },
    include: {
      rolePermissions: {
        include: {
          permission: true,
        },
      },
    },
  });
  if (!role.rolePermissions.some((rp) => rp.permission === "project:manage")) {
    throw new HttpException("Forbidden", 403);
  }
  // Validate status transition: active → archived/completed only
  if (project.status !== "active") {
    throw new HttpException(
      "Only active projects can be archived or completed",
      400,
    );
  }
  // Determine new status and update project
  const newStatus = "archived" as const;
  const updated = await MyGlobal.prisma.hrm_tracker_projects.update({
    where: { id: props.projectId },
    data: {
      status: newStatus,
      updated_at: new Date(),
    },
    select: {
      id: true,
      name: true,
      description: true,
      color: true,
      status: true,
      budget_hours: true,
      start_date: true,
      end_date: true,
      created_at: true,
      updated_at: true,
      deleted_at: true,
      hrm_tracker_organization_id: true,
      organization: HrmTrackerOrganizationAtSummaryTransformer.select(),
    },
  });
  // Create activity log entry
  await MyGlobal.prisma.hrm_tracker_activity_logs.create({
    data: {
      id: v4(),
      action_type:
        newStatus === "archived" ? "project_archived" : "project_completed",
      action_type: "member",
      actor_id: props.member.id,
      session_id: props.member.session_id,
      target_type: "project",
      target_id: project.id,
      hrm_tracker_organization_id: project.hrm_tracker_organization_id,
      created_at: new Date(),
    },
  });
  return await HrmTrackerProjectTransformer.transform(updated);
}

import { IEntity } from "@ORGANIZATION/PROJECT-api/lib/structures/IEntity";
import { IHrmTrackerDepartment } from "@ORGANIZATION/PROJECT-api/lib/structures/IHrmTrackerDepartment";
import { ArrayUtil } from "@nestia/e2e";
import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/sdk";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";

import { MyGlobal } from "../MyGlobal";
import { MemberPayload } from "../decorators/payload/MemberPayload";
import { HrmTrackerDepartmentTransformer } from "../transformers/HrmTrackerDepartmentTransformer";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

export async function putHrmTrackerMemberDepartmentsDepartmentId(props: {
  member: MemberPayload;
  departmentId: string;
  body: IHrmTrackerDepartment.IUpdate;
}): Promise<IHrmTrackerDepartment> {
  const existing =
    await MyGlobal.prisma.hrm_tracker_departments.findUniqueOrThrow({
      where: { id: props.departmentId },
      select: {
        id: true,
        hrm_tracker_organization_id: true,
        parent_id: true,
        name: true,
        deleted_at: true,
      },
    });
  if (existing.deleted_at !== null) {
    throw new HttpException("Department not found", 404);
  }
  const employee = await MyGlobal.prisma.hrm_tracker_employees.findFirst({
    where: {
      organization_id: existing.hrm_tracker_organization_id,
      user_id: props.member.id,
    },
  });
  if (employee === null) {
    throw new HttpException("Forbidden", 403);
  }
  const hasOrgManagePermission =
    await MyGlobal.prisma.hrm_tracker_roles.findFirst({
      where: {
        organization: { id: existing.hrm_tracker_organization_id },
        employee_roles: {
          some: { employee_id: employee.id },
        },
        permissions: {
          some: { permission: "org:manage" },
        },
      },
    });
  if (hasOrgManagePermission === null) {
    throw new HttpException("Forbidden", 403);
  }
  if (props.body.name !== undefined) {
    const existingByName =
      await MyGlobal.prisma.hrm_tracker_departments.findFirst({
        where: {
          organization: { id: existing.hrm_tracker_organization_id },
          name: props.body.name,
          id: {
            not: props.departmentId,
          },
          deleted_at: null,
        },
      });
    if (existingByName !== null) {
      throw new HttpException("Department name already exists", 409);
    }
  }
  if (props.body.parent_id !== undefined) {
    const parentId = props.body.parent_id ?? undefined;
    const parent = await MyGlobal.prisma.hrm_tracker_departments.findUnique({
      where: { id: parentId },
      select: {
        id: true,
        hrm_tracker_organization_id: true,
        deleted_at: true,
      },
    });
    if (parent === null) {
      throw new HttpException("Parent department not found", 404);
    }
    if (parent.deleted_at !== null) {
      throw new HttpException("Parent department not found", 404);
    }
    if (
      parent.hrm_tracker_organization_id !==
      existing.hrm_tracker_organization_id
    ) {
      throw new HttpException(
        "Cross-organization parent department violation",
        400,
      );
    }
    const isSelfReference = parent.id === props.departmentId;
    if (isSelfReference) {
      throw new HttpException("Self-reference not allowed", 400);
    }
    const hasCircularReference =
      await MyGlobal.prisma.hrm_tracker_departments.findFirst({
        where: {
          parent_id: props.departmentId,
          id: parent.id,
          deleted_at: null,
        },
      });
    if (hasCircularReference !== null) {
      throw new HttpException(
        "Circular parent-child relationship not allowed",
        400,
      );
    }
  }
  const updated = await MyGlobal.prisma.hrm_tracker_departments.update({
    where: { id: props.departmentId },
    data: {
      ...(props.body.name !== undefined && { name: props.body.name }),
      ...(props.body.description !== undefined && {
        description: props.body.description ?? null,
      }),
      ...(props.body.parent_id !== undefined && {
        parent_id: props.body.parent_id ?? null,
      }),
      updated_at: new Date().toISOString(),
    },
    ...HrmTrackerDepartmentTransformer.select(),
  });
  return await HrmTrackerDepartmentTransformer.transform(updated);
}

import { IEntity } from "@ORGANIZATION/PROJECT-api/lib/structures/IEntity";
import { ArrayUtil } from "@nestia/e2e";
import { HttpException } from "@nestjs/common";
