  );
  // If no statistics found, return empty data with proper pagination
  if (data.length === 0) {
    return {
      pagination: {
        current: 1,
        limit: 0,
        records: 0,
        pages: 0,
      },
      data: [],
    };
  }
  return {
    pagination: {
      current: 1,
      limit: data.length,
      records: total,
      pages: 1,
    },
    data,
  };
}

